function createKey(){modal('创建 Key',(box,close,overlay)=>{const form=el('form');const name=el('input');name.required=true;const level=el('select');for(const [v,label] of [['read','只读'],['propose','提议'],['write','直接写']]){const o=el('option','',label);o.value=v;level.append(o)}const expiry=el('input');expiry.type='datetime-local';const note=el('textarea');for(const [label,input] of [['名称',name],['权限级别',level],['到期时间（可选）',expiry],['备注（可选）',note]])add(form,add(el('label','',label),input));const actions=el('div','modal-actions');const save=el('button','primary','创建');save.type='submit';add(actions,close,save);form.append(actions);box.append(form);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const result=await api('/api/keys',{method:'POST',body:JSON.stringify({name:name.value,level:level.value,expires_at:expiry.value?new Date(expiry.value).toISOString():'',note:note.value})});clear(box);add(box,el('h2','','Key 已创建'),el('p','muted','请立即复制。关闭后将无法再次查看。'),el('div','secret',result.token));showKeySetup(box,result.token);const done=el('button','primary','完成');done.onclick=()=>{overlay.remove();navigate('keys')};box.append(done)}catch(err){box.append(message(err.message,'error'));save.disabled=false}}})}
$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-error').textContent='';const f=new FormData(e.target);try{const p=await api('/api/auth/login',{method:'POST',body:JSON.stringify({login:f.get('login'),password:f.get('password')})});e.target.reset();showApp(p.login);navigate('overview');showFirstRun()}catch(err){$('#login-error').textContent=err.message}};
