async function renderOverview(){
  add(root,heading('总览','服务与资产清册'));
  const [pending,unverified,outdated,changes,contexts,sites,hosts,networks,services]=await Promise.all([
    api('/api/changes/proposals'),api('/api/assets/unverified'),api('/api/versions/outdated'),api('/api/changes'),api('/api/contexts?archived=false'),
    ...['location','host','network','service'].map(type=>api('/api/browse?type='+type))
  ]);
  const cards=el('div','grid overview-grid');root.append(cards);
  for(const [title,count,view] of [['待确认',pending.length,'pending'],['待核实',unverified.length,'unverified'],['有新版本',outdated.length,'outdated'],['站点',sites.filter(x=>x.fields?.kind==='站点').length,'sites'],['主机',hosts.length,'hosts'],['网段',networks.length,'networks'],['服务',services.length,'assets']]){
    const button=el('button','overview-card');add(button,el('span','muted',title),el('strong','',literal(String(count))));button.onclick=()=>navigate(view);cards.append(button)
  }
  const context=section('共享上下文');const contextButton=el('button','ghost','查看全部');contextButton.onclick=()=>navigate('contexts');context.append(contextButton);
  for(const c of contexts.slice(0,3))context.append(el('p','muted',literal(c.fields?.key||c.name||c.id)));root.append(context);
  const recent=section('最近变更');const more=el('button','ghost','查看全部');more.onclick=()=>navigate('changes');recent.append(more);
  for(const c of changes.slice(0,5))recent.append(el('p','muted',literal(`${c.fields?.action||''} · ${c.fields?.object_id||''} · ${c.created_at||''}`)));root.append(recent)
}
